  5→
  6→/// Generate a kanban.md string from a list of feature states
  7→pub fn generate_kanban_md(features: &[FeatureState]) -> String {
  8→    let now = chrono::Utc::now().format("%Y-%m-%d %H:%M UTC");
  9→
 10→    let mut pending = Vec::new();
 11→    let mut in_progress = Vec::new();
 12→    let mut blocked = Vec::new();
 13→    let mut done = Vec::new();
 14→
 15→    for feature in features {
 16→        match &feature.phase_status {
 17→            PhaseStatus::Pending => pending.push(feature),
 18→            PhaseStatus::InProgress => in_progress.push(feature),
 19→            PhaseStatus::Error => blocked.push(feature),
 20→            PhaseStatus::Completed => done.push(feature),
 21→        }
 22→    }
 23→
 24→    let mut out = String::new();
 25→    out.push_str("# Feature Kanban Board\n");
 26→    out.push_str(&format!("> Last updated: {}\n\n", now));
 27→
 28→    out.push_str("## Pending\n");
 29→    if pending.is_empty() {
 30→        out.push_str("_No pending features_\n");
 31→    } else {
 32→        for f in &pending {
 33→            let phase_name = f
 34→                .get_phase(f.current_phase)
 35→                .map(|p| p.name.as_str())
 36→                .unwrap_or("Unknown");
 37→            out.push_str(&format!("- [ ] **{}** — {}\n", f.feature_name, phase_name));
 38→        }
 39→    }
 40→    out.push('\n');
 41→
 42→    out.push_str("## In Progress\n");
 43→    if in_progress.is_empty() {
 44→        out.push_str("_No features in progress_\n");
 45→    } else {
 46→        for f in &in_progress {
 47→            let phase_name = f
 48→                .get_phase(f.current_phase)
 49→                .map(|p| p.name.as_str())
 50→                .unwrap_or("Unknown");
 51→            let pct = f.completion_percentage();
 52→            out.push_str(&format!(
 53→                "- [→] **{}** — {} ({}%)\n",
 54→                f.feature_name, phase_name, pct
 55→            ));
 56→        }
 57→    }
 58→    out.push('\n');
 59→
 60→    out.push_str("## Blocked\n");
 61→    if blocked.is_empty() {
 62→        out.push_str("_No blocked features_\n");
 63→    } else {
 64→        for f in &blocked {
 65→            let err = f
 66→                .error_state
 67→                .as_deref()
 68→                .unwrap_or("Unknown error");
 69→            out.push_str(&format!(
 70→                "- [✗] **{}** — {}\n",
 71→                f.feature_name, err
 72→            ));
 73→        }
 74→    }
 75→    out.push('\n');
 76→
 77→    out.push_str("## Done\n");
 78→    if done.is_empty() {
 79→        out.push_str("_No completed features_\n");
 80→    } else {
 81→        for f in &done {
 82→            let date = f.last_updated.format("%Y-%m-%d");
 83→            out.push_str(&format!(
 84→                "- [✓] **{}** — completed {}\n",
 85→                f.feature_name, date
 86→            ));
 87→        }
 88→    }
 89→
 90→    out
 91→}
 92→
 93→/// Write kanban.md to the state directory
 94→pub fn write_kanban(state_path: &Path, content: &str) -> Result<()> {
 95→    fs::create_dir_all(state_path)?;
 96→    let path = state_path.join("kanban.md");
 97→    fs::write(path, content)?;
 98→    Ok(())
 99→}
